use std::fs::{File, OpenOptions};
use std::io::{self, Read, Seek, SeekFrom, Write};
use zip::{ZipArchive, ZipWriter, CompressionMethod};
use zip::write::SimpleFileOptions;
struct SparseSink { file: File, pos: u64, length: u64 }
impl Write for SparseSink {
    fn write(&mut self,b:&[u8])->io::Result<usize>{
        if b.len()>=4096 && b.iter().all(|&x|x==0) {
            self.pos=self.file.seek(SeekFrom::Current(b.len() as i64))?;
        } else { self.file.write_all(b)?; self.pos+=b.len() as u64; }
        self.length=self.length.max(self.pos); Ok(b.len())
    }
    fn flush(&mut self)->io::Result<()> { self.file.flush() }
}
impl Seek for SparseSink {
    fn seek(&mut self,from:SeekFrom)->io::Result<u64>{
        let dest=match from { SeekFrom::Start(p)=>Some(p),SeekFrom::Current(d)=>self.pos.checked_add_signed(d),SeekFrom::End(d)=>self.length.checked_add_signed(d) }.ok_or_else(||io::Error::new(io::ErrorKind::InvalidInput,"invalid seek"))?;
        self.pos=self.file.seek(SeekFrom::Start(dest))?; Ok(self.pos)
    }
}
fn sink(label:&str)->SparseSink {
    SparseSink { file: OpenOptions::new().read(true).write(true).create(true).truncate(true).open(format!("/work/tmp/zip-review/fixtures/{label}.zip")).unwrap(), pos:0,length:0 }
}
fn write_large<W:Write+Seek>(mut writer:ZipWriter<W>)->W {
